import java.util.ArrayList;
import java.util.List;

public class Main {
    static ArrayList<String> passed(ArrayList<String> names, ArrayList<Integer> marks) {
        ArrayList<String> result = new ArrayList<>();
        for (int i = 0; i < names.size(); i++) {
            if (marks.get(i) >= 35) {
                result.add(names.get(i));
            }
        }
        return result;
    }

    public static void main(String[] args) {
        ArrayList<String> names = new ArrayList<>(List.of("Ravi", "Sita", "Anu"));
        ArrayList<Integer> marks = new ArrayList<>(List.of(30, 88, 35));
        System.out.println(passed(names, marks));
    }
}

