import java.util.HashSet;

public class Main {
    static int uniqueCount(String[] names) {
        HashSet<String> set = new HashSet<>();
        for (String n : names) {
            set.add(n);
        }
        return set.size();
    }

    public static void main(String[] args) {
        System.out.println(uniqueCount(new String[]{"Ravi", "Sita", "Ravi"}));
    }
}

