import java.util.List;

class Pair<A, B> {
    private final A first;
    private final B second;

    Pair(A first, B second) {
        this.first = first;
        this.second = second;
    }

    A getFirst() {
        return first;
    }

    B getSecond() {
        return second;
    }
}

public class Main {
    static <T> T firstOf(List<T> list) {
        return list.get(0);
    }

    public static void main(String[] args) {
        Pair<String, Integer> student = new Pair<>("Ravi", 82);
        Pair<String, Double> offer = new Pair<>("TCS", 3.6);
        System.out.println(student.getFirst() + " " + student.getSecond());
        System.out.println(offer.getFirst() + " " + offer.getSecond());
        System.out.println(firstOf(List.of("Sita", "Anu")) + " " + firstOf(List.of(5, 9)));
    }
}

