import java.util.List;

class Box<T> {
    private final T item;

    Box(T item) {
        this.item = item;
    }

    T get() {
        return item;
    }
}

public class Main {
    static <T> int countMatches(List<T> list, T value) {
        int n = 0;
        for (T x : list) {
            if (x.equals(value)) {
                n++;
            }
        }
        return n;
    }

    public static void main(String[] args) {
        Box<String> b = new Box<>("Godan");
        System.out.println(b.get() + " " + countMatches(List.of("tea", "coffee", "tea"), "tea") + " " + countMatches(List.of(1, 2, 1, 1), 1));
    }
}

