import java.util.List;
import java.util.Map;
import java.util.TreeSet;

public class Main {
    static String summary(List<String> orders, Map<String, Integer> menu) {
        int total = 0;
        int unknown = 0;
        TreeSet<String> items = new TreeSet<>();
        for (String o : orders) {
            if (menu.containsKey(o)) {
                total += menu.get(o);
                items.add(o);
            } else {
                unknown++;
            }
        }
        return "Bill: Rs " + total + ", Items: " + String.join(", ", items) + ", Unknown: " + unknown;
    }

    public static void main(String[] args) {
        Map<String, Integer> menu = Map.of("tea", 15, "samosa", 12, "dosa", 40);
        System.out.println(summary(List.of("tea", "dosa", "tea", "pizza"), menu));
    }
}
